const bounds = t => { if (!SEG) return null; if (SEGT === t) return SEGB; const b = new Set([0, t.length]); try { for (const s of SEG.segment(t)){ b.add(s.index); b.add(s.index + s.segment.length); } } catch(e){} SEGT = t; SEGB = b; return b; };
const zhEdge = (t, i, j) => { const B = bounds(t), ok = (c, p) => !isHan(c) || (B && B.has(p)) || ZH_GLUE.has(c); return ok(t[i - 1], i) && ok(t[j], j); };
