const NM_TITLE = [[/^(.+?)\s*(医生|大夫)$/, "Dr"], [/^(.+?)\s*老师$/, "Teacher"], [/^(.+?)\s*阿姨$/, "Auntie"], [/^(.+?)\s*叔叔$/, "Uncle"], [/^(.+?)\s*师傅$/, "Master"], [/^(.+?)\s*奶奶$/, "Granny"], [/^(.+?)\s*爷爷$/, "Grandpa"]];
